class gRPCEngine {
    constructor(url, callId) {
        this.callId = callId;
        const urlParam = url.split('?')
        this.host = urlParam[0];
        this.params = {};
        if (urlParam.length > 1) {
            urlParam[1].split('&').forEach(e => {
                const keyValue = e.split('=');
